FILE: app/src/fade-in.ts
```ts
import {
  createPropertyAnimationClip,
  createPropertyAnimationGroup,
  playAnimation,
  type AnimationManager,
  type AnimationGroup,
} from "@babylonjs/lite";

export function fadeIn(
  manager: AnimationManager,
  panel: { alpha: number },
  durationMs: number
): AnimationGroup {
  panel.alpha = 0;

  const clip = createPropertyAnimationClip("fadeIn", [
    {
      path: "alpha",
      keys: [
        { time: 0, value: 0 },
        { time: durationMs / 1000, value: 1 },
      ],
      interpolation: "linear",
    },
  ]);

  const group = createPropertyAnimationGroup(manager, panel, clip, {
    loop: false,
  });

  playAnimation(group);

  return group;
}
```

I created `src/fade-in.ts` which builds a linear property-animation clip with two keyframes (alpha 0 → 1 over `durationMs`), wraps it in a non-looping `AnimationGroup` targeting the panel, and plays it on the given manager. I'm slightly unsure whether `time` in keyframes is measured in seconds (I assumed so, following GLTF conventions) and whether `createPropertyAnimationGroup` auto-plays internally (I call `playAnimation` explicitly to be safe, which should be harmless if it does).
